import { requireVendorSession } from "../../../../lib/vendor-session";
import { uploadVendorMedia, vendorTrustWorkspace } from "../../../../lib/vendor-backoffice-service";
export async function POST(request:Request){try{const p=await requireVendorSession(request,true);const f=await request.formData();const file=f.get("file");if(!(file instanceof File))throw new Error("Media file is required");if(file.size<=0)throw new Error("Media file is empty");const canonicalVariantId=String(f.get("canonicalVariantId")??"").trim();const kind=String(f.get("kind")??"") as "image"|"video"|"document";if(!["image","video","document"].includes(kind))throw new Error("Invalid media kind");await uploadVendorMedia(p,{canonicalVariantId,kind,filename:file.name,contentType:file.type,bytes:new Uint8Array(await file.arrayBuffer()),altText:String(f.get("altText")??"").trim()||undefined,rightsOwner:String(f.get("rightsOwner")??"").trim()});return Response.json(await vendorTrustWorkspace(p));}catch(e){return Response.json({error:e instanceof Error?e.message:"media_upload_failed"},{status:400})}}
